<?php
declare(strict_types=1); require_once __DIR__.'/../src/auth.php'; $message=null;
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $login=trim($_POST['login']??''); if($login!==''){ try{ $s=db()->prepare("SELECT id FROM app_users WHERE status='active' AND (username=:l OR email=:l OR phone=:l) LIMIT 1"); $s->execute(['l'=>$login]); if($id=$s->fetchColumn()) generate_password_reset_token((string)$id); }catch(Throwable $e){} } $message='Solicitação registrada. Entre em contato com o administrador para receber o link.'; }
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recuperar senha</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><div class="login-page"><form class="login-box" method="post"><?=csrf_field()?><h1>Recuperar senha</h1><?php if($message):?><div class="list-card"><strong><?=htmlspecialchars($message)?></strong></div><?php endif;?><div class="form-row"><label>Usuário, e-mail ou telefone</label><input name="login" required></div><button class="btn btn-primary" style="width:100%">Solicitar</button><div style="text-align:center;margin-top:15px"><a class="label" href="/login.php">Voltar</a></div></form></div></body></html>
